targets.query:
from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "midea_raw" and r.device == "${device}")
  |> filter(fn: (r) => r._field == "0x01_7")
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r["0x01_7"])
  |> map(fn: (r) => {
        b = float(v: r["0x01_7"])
        // Two OEM encodings: whole-degree (16–32) or half-degree +50 (82–114)

        return {_time: r._time, _field: "indoor_setpoint", _value: if b < 50.0 then b else (b - 50.0) / 2.0}
     })
  |> group(columns: ["_field"])
  |> sort(columns: ["_time"])
  |> map(fn: (r) => ({ r with _value: r._value * 1.8 + 32.0 }))
  |> last()

import "math"

from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "midea_raw" and r.device == "${device}")
  |> filter(fn: (r) => r._field == "0x01_2" or r._field == "0x02_3")
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r["0x01_2"] and exists r["0x02_3"])
  |> map(fn: (r) => {
        b = float(v: r["0x01_2"])
        // Meaningful only while the compressor runs (0x02[3] > 0); otherwise the
        // ~0.2 A standby baseline measured with a clamp meter (#16)

        return {_time: r._time, _field: "current_draw", _value: if r["0x02_3"] == 0 then 0.2 else math.trunc(x: (0.117 * b + 0.92) * 100.0) / 100.0}
     })
  |> group(columns: ["_field"])
  |> sort(columns: ["_time"])
  |> last()

