  |> filter(fn: (r) => r._field == "0x00_7" or r._field == "0x00_8")
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r["0x00_7"] and exists r["0x00_8"])
  |> map(fn: (r) => {
        // uint16, little-endian

        return {_time: r._time, _field: "outdoor_fan_speed", _value: float(v: r["0x00_7"]) + 256.0 * float(v: r["0x00_8"])}
     })
  |> group(columns: ["_field"])
  |> sort(columns: ["_time"])
