import "math"

from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "midea_raw" and r.device == "${device}")
  |> filter(fn: (r) => r._field == "0x00_6")
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r["0x00_6"])
  |> map(fn: (r) => {
        b = float(v: r["0x00_6"])
        // Steinhart–Hart, rounded to the nearest 1 °C; 0, 254 and 255 are fault codes
        steinhartHart = (b) => {
            l = math.log(x: (255.0 - b) / b)

            return math.round(x: 1.0 / (0.002873 + 0.0002491 * l + 0.000000974 * l * l * l) - 273.15)
        }

        return {_time: r._time, _field: "discharge_temperature", _value: if b == 0.0 then -48.0 else if b >= 254.0 then b else steinhartHart(b: b)}
     })
  |> group(columns: ["_field"])
  |> sort(columns: ["_time"])
  |> map(fn: (r) => ({ r with _value: r._value * 1.8 + 32.0 }))
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: false)

